import { describe, expect, it } from "vitest";
import { generatedBanner, regenerateCommandOf } from "./guide-settings.js";

describe("regenerate command and banner", () => {
  it("defaults to the CLI and names the repository's own command when it has one", () => {
    expect(regenerateCommandOf({})).toBe("npx living-docs write");
    expect(generatedBanner({ regenerateCommand: "npm run docs" })).toBe(
      "<!-- Generated by living-docs — do not edit. Run `npm run docs`. -->",
    );
  });
});
